//! Checks manifest wire format 2 against `docs/test-vectors/manifest-v2.json`,
//! generated by an independent Python implementation
//! (`generate_manifest_v2.py`).

use ourstick_core::{Entry, Manifest, MANIFEST_FORMAT_VERSION};
use serde::Deserialize;

const VECTORS: &str = include_str!("../../../docs/test-vectors/manifest-v2.json");

#[derive(Deserialize)]
struct Document {
    manifest_format_version: u8,
    valid: Vec<Valid>,
    version_1: Old,
    invalid: Vec<Invalid>,
}

#[derive(Deserialize)]
struct Valid {
    name: String,
    partial: bool,
    stick_name: String,
    entries: Vec<EntryVector>,
    bytes: String,
}

#[derive(Deserialize)]
struct Old {
    entries: Vec<EntryVector>,
    bytes: String,
}

#[derive(Deserialize)]
struct Invalid {
    name: String,
    bytes: String,
}

#[derive(Deserialize)]
struct EntryVector {
    path: String,
    size: u64,
    mtime: u64,
    hash: String,
}

fn hex(text: &str) -> Vec<u8> {
    data_encoding::HEXLOWER.decode(text.as_bytes()).unwrap()
}

fn entries(vectors: &[EntryVector]) -> Vec<Entry> {
    vectors
        .iter()
        .map(|vector| Entry {
            path: vector.path.clone(),
            size: vector.size,
            mtime: vector.mtime,
            hash: hex(&vector.hash).try_into().unwrap(),
        })
        .collect()
}

#[test]
fn manifests_match_the_independent_vectors() {
    let document: Document = serde_json::from_str(VECTORS).unwrap();
    assert_eq!(document.manifest_format_version, MANIFEST_FORMAT_VERSION);
    for vector in &document.valid {
        let manifest = Manifest {
            partial: vector.partial,
            name: vector.stick_name.clone(),
            entries: entries(&vector.entries),
        };
        let bytes = hex(&vector.bytes);
        assert_eq!(manifest.to_bytes().unwrap(), bytes, "{}", vector.name);
        assert_eq!(
            Manifest::from_bytes(&bytes).unwrap(),
            manifest,
            "{}",
            vector.name
        );
    }
    let old = Manifest::from_bytes(&hex(&document.version_1.bytes)).unwrap();
    assert_eq!(old.entries, entries(&document.version_1.entries));
    assert!(!old.partial && old.name.is_empty());
    for vector in &document.invalid {
        assert!(
            Manifest::from_bytes(&hex(&vector.bytes)).is_err(),
            "{} was accepted",
            vector.name
        );
    }
}
